15	 * 保证并发交接/取消/核验按事务提交顺序生效。
16	 */
17	@Repository
18	public class EvidenceRepository {
19	
20	    private static final EvidenceRowMapper ROW_MAPPER = new EvidenceRowMapper();
21	
22	    private final JdbcTemplate jdbc;
