24	    public EvidenceRepository(JdbcTemplate jdbc) {
25	        this.jdbc = jdbc;
26	    }
27	
28	    /**
29	     * 插入新证物，初始状态 SEALED，保管人为入库操作人。
30	     */
31	    public void insert(String evidenceKey, String caseKey, String category, String sealNo,
32	                       String custodianId, LocalDateTime now) {
33	        jdbc.update("""
34	                        INSERT INTO evidence
35	                            (evidence_key, case_key, category, seal_no, custodian_id, status, created_at, updated_at)
36	                        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
37	                        """,
38	                evidenceKey, caseKey, category, sealNo, custodianId,
39	                EvidenceStatus.SEALED.name(), now, now);
40	    }
41	
42	    /**
43	     * 按业务键查询（不加锁），用于只读场景。
44	     */
45	    public Optional<Evidence> findByKey(String evidenceKey) {
46	        List<Evidence> rows = jdbc.query(
47	                "SELECT * FROM evidence WHERE evidence_key = ?", ROW_MAPPER, evidenceKey);
48	        return rows.stream().findFirst();
49	    }
50	
51	    /**
52	     * 按业务键查询并锁定证物行（SELECT ... FOR UPDATE），用于一切状态/保管人变更。
53	     */
54	    public Optional<Evidence> findByKeyForUpdate(String evidenceKey) {
55	        List<Evidence> rows = jdbc.query(
56	                "SELECT * FROM evidence WHERE evidence_key = ? FOR UPDATE", ROW_MAPPER, evidenceKey);
57	        return rows.stream().findFirst();
58	    }
59	
60	    /**
61	     * 更新证物状态与保管人（交接接受时原子切换保管人）。
62	     */
63	    public void updateCustody(String evidenceKey, String custodianId, EvidenceStatus status,
64	                              LocalDateTime now) {
65	        jdbc.update(
66	                "UPDATE evidence SET custodian_id = ?, status = ?, updated_at = ? WHERE evidence_key = ?",
67	                custodianId, status.name(), now, evidenceKey);
68	    }
69	
70	    /**
71	     * 仅更新证物状态（交接发起/取消、核验失败）。
72	     */
73	    public void updateStatus(String evidenceKey, EvidenceStatus status, LocalDateTime now) {
74	        jdbc.update(
75	                "UPDATE evidence SET status = ?, updated_at = ? WHERE evidence_key = ?",
76	                status.name(), now, evidenceKey);
77	    }
